end

function UIBattlingUnitComboPanel:Awake()
    self.numOriginPointInRoundStart = 0 
    self.numPointInRound = 0
    local behaviourAction = KTool.GetOrAddComponent(self.controller.gameObject, typeof(BehaviourAction))
    if behaviourAction then
        behaviourAction.OnEnableAction = Bind(self, self.OnEnable)
        --behaviourAction.UpdateAction = Bind(self, self.Update)
        behaviourAction.OnDisableAction = Bind(self, self.OnDisable)
        self.behaviourAction = behaviourAction
    end
    self.cgRootSkillInfo = self.Root_SkillInfo:GetComponent(typeof(CanvasGroup))
    self.cgRootComboPoint = self.Root_ComboPoint:GetComponent(typeof(CanvasGroup))
    self.cgRootComboPoint.alpha = 0
    self.rootSkillDescAnimator = KTool.GetComponent(self.Root_SkillInfo.gameObject, typeof(Animator))
    
    if self.Root_RayCast then
        self.btnShowComboDes = self.Root_RayCast.gameObject
        KTool.GetOrAddComponent(self.btnShowComboDes, typeof(UIEventProxy)).onPointerClick = function()
            self:SetRootShowDesState(true)
        end
    end
    if self.Btn_CloseSkillInfo then
        self.btnCloseComboDes = self.Btn_CloseSkillInfo.gameObject
        KTool.GetOrAddComponent(self.btnCloseComboDes, typeof(UIEventProxy)).onPointerClick = function()
            self:SetRootShowDesState(false)
        end
    end
    local transRootRightPanel = self.controller.transform:Find("Container")
    self.rootRightPanel = KTool.GetComponent(transRootRightPanel.gameObject, typeof(RectTransform))
    xTry(function()
        self:InitComponent()
        self:SetRootShowDesState(false)
        self:SetComboPointsShowStatus(0)
    end)
end

function UIBattlingUnitComboPanel:OnEnable()
    if IsNull(self.eventPanelAction) then
        self.eventPanelAction = Events.AddListener(Constants.EventNames.UIBattlingUnitComboPanelAction, Bind(self, self.PanelAction))
    end
end

function UIBattlingUnitComboPanel:Update()
    if not IsNull(self.catInScene) and not IsNull(self.rootRightPanel) then
        local v3 =  Vector3.New(self.catInScene.position.x, self.catInScene.position.y, self.catInScene.position.z)
        local posInScreen = UIBattlingTools.WorldPointToUIPoint(v3, self.rootRightPanel)
        if self.Root_ComboPoint.anchoredPosition.x ~= posInScreen.x 
                and self.Root_ComboPoint.anchoredPosition.y ~= posInScreen.y then
            self.Root_ComboPoint.anchoredPosition = Vector2.New(posInScreen.x, posInScreen.y + 200)
        end
    else
        if not IsNull(BattleViewMgr.unitCat) then
            self.catInScene = BattleViewMgr.unitCat.transform
        end
    end
end

function UIBattlingUnitComboPanel:Start()
end

function UIBattlingUnitComboPanel:OnDisable()
    if self.eventPanelAction then
        Events.RemoveListener(Constants.EventNames.UIBattlingUnitComboPanelAction, self.eventPanelAction)
        self.eventPanelAction = nil
    end
end

function UIBattlingUnitComboPanel:OnDestroy()
    if self.coRebuildDesc then
        cs_coroutine.stop(self.coRebuildDesc)
    end
    if self.eventPanelAction then
        Events.RemoveListener(Constants.EventNames.UIBattlingUnitComboPanelAction, self.eventPanelAction)
        self.eventPanelAction = nil
    end
    if not IsNull(self.behaviourAction) then
        self.behaviourAction.OnEnableAction = nil
        --self.behaviourAction.UpdateAction = nil
        self.behaviourAction.OnDisableAction = nil
        self.behaviourAction = nil
    end
    self.controller = nil--luabehaviour 中CSharp对象
    self:Delete()
    self = nil
end

