------------ PanelAction ------------
---PanelAction
---@param data table 表现界面事件
function UIBattlingUnitComboPanel:PanelAction(data)
    if data.eventType == Constants.UnitPanelAction.SetRootShowState then
        local showState = data.showState
        self:SetRootComboPointShowState(showState)
    elseif data.eventType == Constants.UnitPanelAction.SetComboPoint then
        local trailPosStart = data.trailStart
        self:SetComboPoint(trailPosStart)
    elseif data.eventType == Constants.UnitPanelAction.SetRootDefault then
        self:SetPanelComboPointRootDefault()
    elseif data.eventType == Constants.UnitPanelAction.SetPanelDefault then
        self:SetPanelDefault()
    end
end
