------------ SetData ------------
function UIBattlingUnitComboPanel:SetSkillData(skillId)
    if skillId <= 0 then return end
    ---@type UIBattlingTools
    UIBattlingTools = import("Game.UI.UIBattling.UIBattlingTools")
    local skillName = UIBattlingTools.GetSkillCardInfoBySkillId(skillId, 1).skillName
    self.Txt_SkillName.text = localize("_name2_", { _name2_ = skillName })
    local skillDes_1 = UIBattlingTools.GetSkillCardInfoBySkillId(skillId, 2).skillDesc_2
    local skillDes_2 = UIBattlingTools.GetSkillCardInfoBySkillId(skillId, 3).skillDesc_3
    local skillDes_3 = UIBattlingTools.GetSkillCardInfoBySkillId(skillId, 4).skillDesc_4
    self.Txt_SkillDes_1.text = skillDes_1
    self.Txt_SkillDes_2.text = skillDes_2
    self.Txt_SkillDes_3.text = skillDes_3
    self.unitSkillVo = CfUtils.GetCfVo(AutoIds.IdSetting569, "UnitSkillVo", skillId)
    if isNull(self.unitSkillVo) then return end
    local skillImgPath = self.unitSkillVo.photo2Path
    for i, icon in ipairs(self.listSkillIconDesc) do
        icon:LoadSprite(skillImgPath)
    end
    for i, icon in pairs(self.listSkillIconColor) do
        icon.color = Color.white
    end
    self:SetRootSkillIcon(self.numPointInRound)
    self:SetTxtPointValue(self.numPointInRound)
    self.coRebuildDesc = cs_coroutine.start(function()
        for i = 1, 3 do
            cs_coroutine.yield_return()
        end
        CS.UnityEngine.UI.LayoutRebuilder.ForceRebuildLayoutImmediate(self.Root_SkillInfo)
    end)
end
