---SetComboPoint
---设置连协点
function UIBattlingUnitComboPanel:SetComboPoint(posStart, ptcLayer)
    if self.numOriginPointInRoundStart >= UNIT_COMBO_VALUE_MAX or self.numPointInRound >= UNIT_COMBO_VALUE_MAX then return end
    --- 设置和卡技点数
    if UIBattlingCtrlMgr:GetInstance():GetBooleanPlayerInput() then
        local pointNow = self.numPointInRound + 1
        self.numPointInRound = pointNow >= UNIT_COMBO_VALUE_MAX and UNIT_COMBO_VALUE_MAX or pointNow
    else
        self.numOriginPointInRoundStart = self.numOriginPointInRoundStart + 1
        self.numPointInRound = self.numPointInRound + 1
    end
    --- 技能点
    local goTrail = UIBattlingTools.ReloadPTCOfBattling(Constants.UIBattlingObjPoolPTC.PTC_TRAIL_UNIT, self.controller.gameObject, 1)
    if ptcLayer then
        UIBattlingTools.SetGOTrailRendererChildrenLayer(goTrail, ptcLayer)
        UIBattlingTools.SetPTCOrderInLayer(goTrail, ptcLayer)
    end
    goTrail.transform.position = posStart.transform.position
    --local catInScene = BattleViewMgr.unitCat
    --local catPosInScreen
    --if not IsNull(catInScene) then
    --    catPosInScreen = UIBattlingTools.GetCharacterUIPositionByV3(catInScene.transform.position)
    --end
    --local transEnd = IsNull(catInScene) and self.Root_ComboPoint.transform.position or catPosInScreen
    local transEnd = self.Root_ComboPoint.transform.position
    if IsNull(transEnd) then return end
    UIBattlingTools.PlayAudio(UISheets.UI_Battle.ui_skill_card_fusion_04)
    goTrail.transform:DOMove(transEnd, 0.2):OnComplete(function()
        local goBlink = UIBattlingTools.ReloadPTCOfBattling(Constants.UIBattlingObjPoolPTC.PTC_UNITPOINT_BLINK, self.controller.gameObject, 1)
        if ptcLayer then
            UIBattlingTools.SetPTCOrderInLayer(goBlink, ptcLayer)
        end
        UIBattlingTools.PlayAudio(UISheets.UI_Battle.ui_skill_card_fusion_05)
        goBlink.transform.position = transEnd
    end)
    self:SetRootSkillIcon(self.numPointInRound) 
    self:SetTxtPointValue(self.numPointInRound)
    self:PlayAnimationPointChange()
end

function UIBattlingUnitComboPanel:SetComboPointsShowStatus(value)
    value = checkNumber(value)
    for i, point in ipairs(self.listPoints) do
        point.Status = i <= self.numPointInRound and 2 or 1
    end
end

function UIBattlingUnitComboPanel:SetRootSkillIcon(point)
    Events.Broadcast(Constants.EventNames.UIBattleUpdateUnitSkillPoint, checkNumber(point))
end

function UIBattlingUnitComboPanel:SetTxtPointValue(point)
    xTry(function() 
        KTool.SetActive(self.ImgActivated.gameObject, point > 1)
        KTool.SetActive(self.Txt_ActiveInfo.gameObject, point < 2)
        self:UpdateActiveNode(point)
        self:UpdateDescNodeImg(point)
        self:UpdateDescNodeTxt(point)
        --self:UpdateHighLineDescNode(point)
    end)
end

---SetRootComboPointShowState
---合成点数 展示状态
function UIBattlingUnitComboPanel:SetRootComboPointShowState(boolean)
    boolean = checkBool(boolean)
    if not IsNull(self.cgRootComboPoint) then
        self.cgRootComboPoint.alpha = boolean and 1 or 0
    end
end

