---SetPanelDefault
---设置panel到默认状态
function UIBattlingUnitComboPanel:SetPanelDefault()
    self:SetRootShowDesState(false)
    self.numOriginPointInRoundStart = 0
    self.numPointInRound = 0
    self:SetPanelComboPointRootDefault()
end

---SetPanelComboPointRootDefault
---还原连协点节点
function UIBattlingUnitComboPanel:SetPanelComboPointRootDefault()
    self.numPointInRound = self.numOriginPointInRoundStart
    self:SetRootSkillIcon(self.numPointInRound)
    self:SetTxtPointValue(self.numPointInRound)
    self:PlayAnimationPointChange()
end

---SetPanelShowState
---设置 界面 显示状态
---@param skillId number
function UIBattlingUnitComboPanel:SetPanelShowState(skillId)
    skillId = checkNumber(skillId)
    KTool.SetActive(self.controller.gameObject, not IsNull(skillId) and checkNumber(skillId) > 0)
    if skillId then
        self:SetSkillData(skillId)
    end
end

function UIBattlingUnitComboPanel:UpdateActiveNode(index)
    index = index - 1
    for i, nodeArray in pairs(self.listSwitchImgDescPoints) do
        for j = 1, nodeArray.Length do
            nodeArray[j - 1].Status = 1
        end
    end
    if index <= 0 then return end
    local nodeArray = self.listSwitchImgDescPoints[index]
    for i = 1, nodeArray.Length do
        nodeArray[i - 1].Status = 2
    end
end

function UIBattlingUnitComboPanel:UpdateDescNodeImg(index)
    index = index - 1
    for i, icon in pairs(self.listSkillIconDesc) do
        icon:LoadSprite(self.unitSkillVo.photoPath)
    end
    for i, icon in pairs(self.listSkillIconColor) do
        icon.color = Color.New(0.706,0.706,0.706,1)
    end
    if index <= 0 then return end
    local icon = self.listSkillIconDesc[index]
    if not IsNull(icon) then
        icon:LoadSprite(self.unitSkillVo.photo2Path)
    end
    local iconColor = self.listSkillIconColor[index]
    if not isNull(iconColor) then
        iconColor.color = Color.white
    end
end

function UIBattlingUnitComboPanel:UpdateDescNodeTxt(index)
    index = index - 1
    for i, txt in pairs(self.listSwitchTextDesc) do
        txt.Status = 1
    end
    if index <= 0 then return end
    local txt = self.listSwitchTextDesc[index]
    txt.Status = 2
end

function UIBattlingUnitComboPanel:UpdateHighLineDescNode(index)
    index = index - 1
    for i, trans in pairs(self.listHighLine) do
        KTool.SetActive(trans.gameObject, false)
    end
    if index <= 0 then return end
    KTool.SetActive(self.listHighLine[index].gameObject, true)
end

function UIBattlingUnitComboPanel:PlayAnimationPointChange()
    xTry(function() 
        for i, point in ipairs(self.listPoints) do
            point.Status = i <= self.numPointInRound and 2 or 1
        end
    end)
end

return UIBattlingUnitComboPanel
